import{_ as e,c as n,o as s,ag as t}from"./chunks/framework.CQuhCYrb.js";const m=JSON.parse('{"title":"Rstudio","description":"","frontmatter":{"title":"Rstudio"},"headers":[],"relativePath":"general/rstudio.md","filePath":"general/rstudio.md","lastUpdated":null}'),i={name:"general/rstudio.md"};function r(o,a,l,p,d,c){return s(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="rstudio" tabindex="-1">Rstudio <a class="header-anchor" href="#rstudio" aria-label="Permalink to &quot;Rstudio&quot;">​</a></h1><h2 id="rstudio-analysis-guide" tabindex="-1">RStudio Analysis Guide <a class="header-anchor" href="#rstudio-analysis-guide" aria-label="Permalink to &quot;RStudio Analysis Guide&quot;">​</a></h2><h3 id="introduction-to-social-statistics" tabindex="-1">Introduction to Social Statistics <a class="header-anchor" href="#introduction-to-social-statistics" aria-label="Permalink to &quot;Introduction to Social Statistics&quot;">​</a></h3><p>Social statistics are pivotal for comprehending, explaining, and predicting social phenomena. Here’s a deeper dive into some definitions and fundamental concepts, with practical examples highlighting their importance. RStudio is a powerful tool for data analysis, offering numerous functions for statistical analysis and data visualization. Here’s an introduction to some basic yet essential R commands, explanations, and examples for calculating mean, standard deviation, and variance and creating basic charts or graphs.</p><p>It is important to know how to analyze data based on your research questions and hypothesis. For that reason, review this guide during the planning phase of your research and then return to it during the analysis phase.</p><h3 id="terms" tabindex="-1">Terms <a class="header-anchor" href="#terms" aria-label="Permalink to &quot;Terms&quot;">​</a></h3><p>Mean (Average) The mean is the sum of all values divided by the number of values. It’s commonly used as a general indicator of the data’s central tendency. <strong>Example</strong>: The mean income in a neighborhood can provide an idea of the economic status of its residents.</p><p>Median The median is the middle value of a dataset when ordered. It’s particularly useful when the data has outliers that skew the mean. <strong>Example</strong>: Median housing prices are often reported as they give a better sense of the market’s central tendency without distortion from extremely high or low values.</p><p>Mode The mode is the most frequently occurring value in a dataset and can highlight the most common characteristic within a sample. <strong>Example</strong>: In fashion retail, the mode can indicate the most common dress size sold, informing stock decisions.</p><p>Variance Variance quantifies the spread of data points around the mean, which is crucial for assessing data distribution. <strong>Example</strong>: Variance in test scores across schools can indicate educational disparities.</p><p>Standard Deviation Standard deviation measures the variation from the mean, providing a sense of data dispersion. <strong>Example</strong>: The standard deviation of investment returns can help investors understand potential risk.</p><p>Correlation Correlation assesses the relationship between two variables, ranging from -1 to 1. High absolute values imply strong relationships. <strong>Example</strong>: A high correlation between education and income may suggest that higher education levels can lead to higher earnings.</p><p>Dependent and Independent Variables In a study, the researcher is interested in explaining or predicting the dependent variable, while the independent variable is believed to influence the dependent variable. <strong>Example</strong>: In health research, patient recovery time (dependent variable) may be influenced by treatment type (independent variable).</p><p>R and R-Squared ‘R’ is the correlation coefficient, while ‘R-squared’ measures the proportion of variation in the dependent variable that can be explained by the independent variable(s) in a regression model. <strong>Example</strong>: An R-squared value in a marketing campaign effectiveness study can show how well changes in ad spending predict sales variations.</p><p>P-value The p-value assesses the strength of evidence against a null hypothesis, with low values indicating statistical significance. <strong>Example</strong>: A low p-value in drug efficacy studies could indicate a significant effect of the drug on improving patient outcomes.</p><p>Bell Curve (Normal Distribution) The bell curve is a graphical representation of a normal distribution, depicting how data is dispersed in relation to the mean. <strong>Example</strong>: IQ scores typically follow a bell curve, with most people scoring around the average and fewer at the extremes.</p><h3 id="statistical-tools-and-concepts" tabindex="-1">Statistical Tools and Concepts <a class="header-anchor" href="#statistical-tools-and-concepts" aria-label="Permalink to &quot;Statistical Tools and Concepts&quot;">​</a></h3><p>Regression Model A regression model predicts the value of a dependent variable based on the values of one or more independent variables. It’s a crucial tool in data analysis for understanding and quantifying relationships. <strong>Example</strong>: A business analyst might use a regression model to understand how sales revenue (dependent variable) is affected by advertising spend and price adjustments (independent variables). <strong>Data to Look For</strong>: Sales data, advertising budget, historical pricing data, and sales channels.</p><p>ANOVA (Analysis of Variance) ANOVA is a statistical technique used to determine if there are any statistically significant differences between the means of three or more independent (unrelated) groups. <strong>Example</strong>: Researchers may use ANOVA to compare test scores between students from different classrooms to understand if teaching methods significantly impact performance. <strong>Data to Look For</strong>: Test scores from multiple classrooms, information on teaching methods, and student demographics.</p><p>Chi-Square Test The Chi-Square test determines if there is a significant association between categorical variables. It’s widely used in survey research. <strong>Example</strong>: A sociologist might use a Chi-Square test to see if voting preference is independent of gender. <strong>Data to Look For</strong>: Survey responses on voting preferences and demographic data, including gender.</p><p>Multivariate Regression Multivariate regression models the simultaneous relationships between multiple independent variables and more than one dependent variable. <strong>Example</strong>: Health researchers could use multivariate regression to study the impact of diet and exercise on blood pressure and cholesterol levels. <strong>Data to Look For</strong>: Dietary intake records, exercise logs, blood pressure measurements, and cholesterol readings.</p><p>Logistic Regression Logistic regression is used to model a binary outcome’s probability based on one or more predictor variables. <strong>Example</strong>: In credit scoring, logistic regression could help predict whether someone will default on a loan based on their financial history. <strong>Data to Look For</strong>: Credit history, loan repayment records, demographic and financial background information.</p><p>Time Series Analysis Time series analysis involves data analysis methods to extract meaningful statistics and trends over time. <strong>Example</strong>: Economists might use time series analysis to forecast future economic activity based on past trends. <strong>Data to Look For</strong>: Historical economic indicators, stock market data, inflation rates, and unemployment figures.</p><p>Survival Analysis Survival analysis analyzes the expected duration until one or more events occur, such as death, pregnancy, job change, etc. <strong>Example</strong>: Medical researchers use survival analysis to estimate the time until a patient may experience remission. <strong>Data to Look For</strong>: Patient follow-up data, time-to-event data, treatment information, and covariates that may influence survival.</p><h3 id="types-of-data-and-format-headers" tabindex="-1">Types of Data and Format Headers <a class="header-anchor" href="#types-of-data-and-format-headers" aria-label="Permalink to &quot;Types of Data and Format Headers&quot;">​</a></h3><p>Data comes in various forms, and understanding how to format it correctly is crucial for analysis. Here are examples of dataset structures for different types of analyses involving locations, populations, and events. These examples include formatting for datasets that require handling dependent, independent, and multivariable datasets.</p><p>Consider the <a href="/research/research-datasets.html">research datasets</a> section or the community datasets section</p><h3 id="nominal-data-categorical-without-order" tabindex="-1">Nominal Data (Categorical without Order) <a class="header-anchor" href="#nominal-data-categorical-without-order" aria-label="Permalink to &quot;Nominal Data (Categorical without Order)&quot;">​</a></h3><p>Example dataset for locations (City, Country, Region):</p><table tabindex="0"><thead><tr><th>City</th><th>Country</th><th>Region</th></tr></thead><tbody><tr><td>New York</td><td>United States</td><td>North America</td></tr><tr><td>Tokyo</td><td>Japan</td><td>Asia</td></tr><tr><td>Paris</td><td>France</td><td>Europe</td></tr></tbody></table><h3 id="ordinal-data-categorical-with-order" tabindex="-1">Ordinal Data (Categorical with Order) <a class="header-anchor" href="#ordinal-data-categorical-with-order" aria-label="Permalink to &quot;Ordinal Data (Categorical with Order)&quot;">​</a></h3><p>Example dataset for survey responses (Satisfaction Level). Useful for understanding the order of responses but not the magnitude of differences between them:</p><table tabindex="0"><thead><tr><th>RespondentID</th><th>SatisfactionLevel</th></tr></thead><tbody><tr><td>1</td><td>Satisfied</td></tr><tr><td>2</td><td>Neutral</td></tr><tr><td>3</td><td>Dissatisfied</td></tr></tbody></table><p>To understand the magnitude of differences between responses, you’d need to use interval or ratio data. Ordinal Data can be converted to interval or ratio data by assigning numerical values to the categories (e.g., 1 for Dissatisfied, 2 for Neutral, 3 for Satisfied).</p><h3 id="interval-and-ratio-data-survey-responses-satisfaction-level" tabindex="-1">Interval and Ratio Data (Survey Responses: Satisfaction Level) <a class="header-anchor" href="#interval-and-ratio-data-survey-responses-satisfaction-level" aria-label="Permalink to &quot;Interval and Ratio Data (Survey Responses: Satisfaction Level)&quot;">​</a></h3><p>Useful for understanding the magnitude of differences between responses, the mean and standard deviation can be calculated for interval and ratio data.</p><table tabindex="0"><thead><tr><th>RespondentID</th><th>SatisfactionLevel</th></tr></thead><tbody><tr><td>1</td><td>7</td></tr><tr><td>2</td><td>5</td></tr><tr><td>3</td><td>3</td></tr></tbody></table><h3 id="interval-and-ratio-data-numeric-data" tabindex="-1">Interval and Ratio Data (Numeric Data) <a class="header-anchor" href="#interval-and-ratio-data-numeric-data" aria-label="Permalink to &quot;Interval and Ratio Data (Numeric Data)&quot;">​</a></h3><p>Interval data example for temperature readings in Celsius (without a true zero point). Useful for understanding temperature changes over time:</p><table tabindex="0"><thead><tr><th>City</th><th>MorningTemp</th><th>NoonTemp</th><th>EveningTemp</th></tr></thead><tbody><tr><td>New York</td><td>15</td><td>22</td><td>18</td></tr><tr><td>Tokyo</td><td>20</td><td>28</td><td>25</td></tr><tr><td>Paris</td><td>12</td><td>18</td><td>14</td></tr></tbody></table><p>Ratio data example for population size (has a true zero point). Useful for understanding the population changes over time:</p><table tabindex="0"><thead><tr><th>City</th><th>Population2010</th><th>Population2020</th></tr></thead><tbody><tr><td>New York</td><td>8175133</td><td>8336817</td></tr><tr><td>Tokyo</td><td>13074000</td><td>13929286</td></tr><tr><td>Paris</td><td>2243833</td><td>2148271</td></tr></tbody></table><h3 id="multivariable-datasets" tabindex="-1">Multivariable Datasets <a class="header-anchor" href="#multivariable-datasets" aria-label="Permalink to &quot;Multivariable Datasets&quot;">​</a></h3><p>Example with two or more tables required for dependent, independent variables:</p><p><strong>Table 1: Economic Data by Country</strong></p><table tabindex="0"><thead><tr><th>Country</th><th>GDP2010 (billions)</th><th>GDP2020 (billions)</th></tr></thead><tbody><tr><td>United States</td><td>14964.4</td><td>21427.7</td></tr><tr><td>Japan</td><td>5700.1</td><td>5065.2</td></tr><tr><td>France</td><td>2649.0</td><td>2715.5</td></tr></tbody></table><p><strong>Table 2: Education Data by Country</strong></p><table tabindex="0"><thead><tr><th>Country</th><th>AvgYearsOfSchooling2010</th><th>AvgYearsOfSchooling2020</th></tr></thead><tbody><tr><td>United States</td><td>12</td><td>13</td></tr><tr><td>Japan</td><td>11</td><td>12</td></tr><tr><td>France</td><td>11</td><td>12</td></tr></tbody></table><p>Note: In R, you’d typically handle these datasets as separate data frames or Tibbles and might use join operations to combine them based on common keys (e.g., Country) for analysis.</p><h3 id="significance-of-messaging-campaign-or-operation-on-behavior" tabindex="-1">Significance of Messaging Campaign or Operation on Behavior <a class="header-anchor" href="#significance-of-messaging-campaign-or-operation-on-behavior" aria-label="Permalink to &quot;Significance of Messaging Campaign or Operation on Behavior&quot;">​</a></h3><p>Understanding the impact of messaging campaigns or operations on behavior is crucial in various fields, such as marketing, public health, and social policy. Data analysis plays a pivotal role in assessing these impacts by quantifying changes in behavior and providing insights into the effectiveness of these campaigns.</p><h4 id="key-variables-to-consider" tabindex="-1">Key Variables to Consider <a class="header-anchor" href="#key-variables-to-consider" aria-label="Permalink to &quot;Key Variables to Consider&quot;">​</a></h4><ul><li><p>*<em>&#39;Pre- and Post-Campaign Survey Results</em>&#39;*: Collecting data on individuals’ attitudes, knowledge, or behaviors before and after exposure to a campaign allows for direct assessment of the campaign’s impact.</p></li><li><p><code>*</code><em>Sales Data</em>**: Sales data can be used to measure the impact of marketing campaigns on consumer behavior.</p></li><li><p><code>*</code><em>Event Attendance</em>**: Data on event attendance can be used to measure the impact of public health or social policy campaigns on participation in related activities.</p></li><li><p><code>*</code><em>Economic Indicators/Purchasing Data</em>**: Marketing campaigns can use economic indicators and purchasing data to measure their impact on consumer behavior.</p></li><li><p><code>*</code><em>Engagement Metrics</em>**: Data on online campaigns might include website visits, time spent on the site, click-through rates, social media engagement (likes, shares), and more.</p></li></ul><h4 id="example-of-behavior-change-that-can-and-cannot-be-assessed" tabindex="-1">Example of Behavior Change That Can and Cannot Be Assessed <a class="header-anchor" href="#example-of-behavior-change-that-can-and-cannot-be-assessed" aria-label="Permalink to &quot;Example of Behavior Change That Can and Cannot Be Assessed&quot;">​</a></h4><p>✅ Can Be Assessed: An increase/decrease in recycling rates following an environmental awareness campaign can be measured through surveys or municipal waste data.</p><p>✅ Can Be Assessed: Sales data can measure an increase or decrease in product sales following a marketing campaign.</p><p>✅ Can Be Assessed: An increase/decrease in attendance at a public health event following a public health campaign can be measured through event attendance data.</p><p>✅ Can Be Assessed: Web analytics can measure an increase or decrease in website visits following a digital marketing campaign.</p><p>✅ Can Be Assessed: Social media analytics can measure an increase or decrease in engagement following a social media campaign.</p><p>❌ Cannot Be Assessed Easily: Changes in attitudes or knowledge following a public awareness campaign may require pre- and post-campaign surveys to assess the campaign’s impact.</p><p>❌ Cannot Be Assessed Easily: Changes in deeply held beliefs or attitudes, such as political views, may not be immediately observable or directly translate into measurable behaviors.</p><p>❌ Cannot Be Assessed Easily: Changes in long-term health outcomes following a public health campaign may require long-term follow-up and control groups to assess the campaign’s impact.</p><p>❌ Cannot Be Assessed Easily: Changes in social norms or cultural attitudes may be difficult to measure directly and require more qualitative or indirect measures.</p><h4 id="common-errors-and-pitfalls-when-starting-research" tabindex="-1">Common Errors and Pitfalls When Starting Research <a class="header-anchor" href="#common-errors-and-pitfalls-when-starting-research" aria-label="Permalink to &quot;Common Errors and Pitfalls When Starting Research&quot;">​</a></h4><ul><li>*<em>&#39;Selection Bias</em>&#39;*: Not adequately representing the target population in pre- and post-campaign surveys can lead to skewed results.</li></ul><p><strong><code>*</code><em>Confirmation Bias</em></strong>: Interpreting data to confirm preconceived notions about the campaign’s effectiveness without objectively considering all evidence.</p><ul><li><code>*</code><em>Overlooking External Factors</em>**: Failing to account for external events or trends that may influence behavior independently of the campaign (e.g., a new law or cultural shift).</li></ul><p><strong><code>*</code><em>Insufficient Pre-Campaign Data</em></strong>: Starting data collection without establishing a baseline for comparison can make it challenging to attribute changes in behavior directly to the campaign.</p><p><strong><code>*</code><em>Assuming Immediate Impact</em></strong>: Some campaigns may delay behavior, leading to premature conclusions about their ineffectiveness if immediate post-campaign data is the sole focus.</p><p>By carefully planning research and being mindful of these considerations and potential pitfalls, analysts can more accurately assess the impact of messaging campaigns on behavior.</p><h3 id="installation-and-configuration-of-r-and-rstudio" tabindex="-1">Installation and Configuration of R and RStudio <a class="header-anchor" href="#installation-and-configuration-of-r-and-rstudio" aria-label="Permalink to &quot;Installation and Configuration of R and RStudio&quot;">​</a></h3><p>Walkthrough of the steps to install R and RStudio, and how to configure the environment for optimal performance.</p><p>Download on non-government systems <a href="https://posit.co/download/rstudio-desktop/" target="_blank" rel="noreferrer">here</a></p><h3 id="web-rstudio-server" tabindex="-1">Web: RStudio Server <a class="header-anchor" href="#web-rstudio-server" aria-label="Permalink to &quot;Web: RStudio Server&quot;">​</a></h3><p>See the IrregularChat RStudio Server: <a href="https://rstudio.researchtools.net" target="_blank" rel="noreferrer">IrregularChat RStudio Server</a></p><p>Contact an admin to create an account.</p><h3 id="macos" tabindex="-1">MacOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;MacOS&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>brew install r</span></span>
<span class="line"><span>brew cask install rstudio</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt-get install r-base # install R from the Ubuntu repositories</span></span>
<span class="line"><span>sudo apt-get install gdebi-core # install gdebi-core, a tool to install .deb packages</span></span>
<span class="line"><span>cd /tmp # change to the /tmp directory to download the RStudio .deb package</span></span>
<span class="line"><span>wget https://download1.rstudio.org/electron/jammy/amd64/rstudio-2023.12.1-402-amd64.deb # download the RStudio .deb package</span></span>
<span class="line"><span>sudo apt install ./rstudio-2023.12.1-402-amd64.deb # install the RStudio .deb package using apt</span></span>
<span class="line"><span>cd - # change back to the previous directory</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="packages-to-install-for-processing-and-analysis" tabindex="-1">Packages to Install for Processing and Analysis <a class="header-anchor" href="#packages-to-install-for-processing-and-analysis" aria-label="Permalink to &quot;Packages to Install for Processing and Analysis&quot;">​</a></h3><p>List of essential R packages such as <code>tidyverse</code>, <code>caret</code>, <code>tm</code>, <code>foreign</code>, and <code>haven</code> that are widely used in data analysis and how to install them.</p><ul><li>tidyverse is a collection of R packages designed for data science and includes ggplot2, dplyr, tidyr, readr, purrr, tibble, stringr, forcats, and other packages.</li><li>caret is a set of functions that attempt to streamline the process for creating predictive models.</li><li>tm is a text mining package that provides framework for text mining applications within R.</li><li>haven is used to import and export data from SAS, SPSS, and Stata.</li></ul><h4 id="list-of-essential-packages-for-data-analysis" tabindex="-1">List of essential packages for data analysis <a class="header-anchor" href="#list-of-essential-packages-for-data-analysis" aria-label="Permalink to &quot;List of essential packages for data analysis&quot;">​</a></h4><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>packages &lt;- c(&quot;tidyverse&quot;, &quot;ggplot2&quot;, &quot;caret&quot;, &quot;tm&quot;, &quot;foreign&quot;, &quot;haven&quot;) # List of essential packages for data analysis add more if needed</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h4 id="loop-to-install-and-load-packages" tabindex="-1">Loop to install and load packages <a class="header-anchor" href="#loop-to-install-and-load-packages" aria-label="Permalink to &quot;Loop to install and load packages&quot;">​</a></h4><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>for (pkg in packages) {</span></span>
<span class="line"><span>  if (!require(pkg, character.only = TRUE)) {</span></span>
<span class="line"><span>    install.packages(pkg)</span></span>
<span class="line"><span>    library(pkg, character.only = TRUE)</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h4 id="verify-packages-are-loaded" tabindex="-1">Verify packages are loaded <a class="header-anchor" href="#verify-packages-are-loaded" aria-label="Permalink to &quot;Verify packages are loaded&quot;">​</a></h4><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>loaded_packages &lt;- sapply(packages, require, character.only = TRUE)</span></span>
<span class="line"><span>print(loaded_packages)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h3 id="top-basic-commands-in-r" tabindex="-1">Top Basic Commands in R <a class="header-anchor" href="#top-basic-commands-in-r" aria-label="Permalink to &quot;Top Basic Commands in R&quot;">​</a></h3><p>R is a powerful tool for data analysis, offering numerous functions for statistical analysis and data visualization. Here’s an introduction to some basic yet essential R commands, along with explanations and examples for calculating mean, standard deviation, and variance and creating basic charts or graphs.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>1. Installing and loading packages</span></span>
<span class="line"><span>install.packages(&quot;ggplot2&quot;) # Install a package, ggplot2 for example</span></span>
<span class="line"><span>library(ggplot2) # Load the ggplot2 package for data visualization</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Reading data</span></span>
<span class="line"><span>data &lt;- read.csv(&quot;data.csv&quot;) # Load data from a CSV file into a data frame</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Viewing data</span></span>
<span class="line"><span>View(data) # Open a spreadsheet-like view of the data in RStudio</span></span>
<span class="line"><span>head(data) # View the first few rows of the data frame</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Summarizing data</span></span>
<span class="line"><span>summary(data) # Get a statistical summary of the data (min, 1st Qu., median, mean, 3rd Qu., max)</span></span>
<span class="line"><span>str(data) # Display the structure of the data frame (column names, data types, etc.)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Calculating basic statistics</span></span>
<span class="line"><span>mean_data &lt;- mean(data$variable, na.rm = TRUE) # Calculate mean of a variable, excluding NA values</span></span>
<span class="line"><span>sd_data &lt;- sd(data$variable, na.rm = TRUE) # Calculate standard deviation of a variable, excluding NA values</span></span>
<span class="line"><span>var_data &lt;- var(data$variable, na.rm = TRUE) # Calculate variance of a variable, excluding NA values</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Comparing two variables - Scatter plot</span></span>
<span class="line"><span>ggplot(data, aes(x = variable1, y = variable2)) +</span></span>
<span class="line"><span>  geom_point() + # Create a scatter plot</span></span>
<span class="line"><span>  labs(title = &quot;Scatter Plot of Variable1 vs. Variable2&quot;, x = &quot;Variable 1&quot;, y = &quot;Variable 2&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Comparing means - Boxplot</span></span>
<span class="line"><span>ggplot(data, aes(x = factor_variable, y = numeric_variable)) +</span></span>
<span class="line"><span>  geom_boxplot() + # Create a boxplot</span></span>
<span class="line"><span>  labs(title = &quot;Boxplot of Numeric Variable by Factor&quot;, x = &quot;Factor Variable&quot;, y = &quot;Numeric Variable&quot;)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br></div></div><h3 id="basic-data-cleaning-commands" tabindex="-1">Basic Data Cleaning Commands <a class="header-anchor" href="#basic-data-cleaning-commands" aria-label="Permalink to &quot;Basic Data Cleaning Commands&quot;">​</a></h3><p>Data cleaning is an essential part of any data analysis process. This section includes commands for handling missing values, outliers, and data transformation.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>1. Commented examples of basic data cleaning commands</span></span>
<span class="line"><span>na.omit(data) # Removes all rows with NA values</span></span>
<span class="line"><span>data[&gt; x](data$column) # Identifies values greater than x in a column</span></span>
<span class="line"><span>log(data$column) # Applies a logarithmic transformation to a column</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Filtering data</span></span>
<span class="line"><span>library(dplyr)</span></span>
<span class="line"><span>filtered_data &lt;- filter(data, column &gt; x) # Use dplyr to filter rows where &#39;column&#39; values are greater than x</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Selecting specific columns</span></span>
<span class="line"><span>selected_data &lt;- select(data, column1, column2) # Use dplyr to select only &#39;column1&#39; and &#39;column2&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Removing duplicate rows</span></span>
<span class="line"><span>data &lt;- distinct(data)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Resetting row numbers after filtering or subsetting</span></span>
<span class="line"><span>data &lt;- data %&gt;% mutate(row_number = row_number()) # Adds a new column &#39;row_number&#39; as a unique identifier</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Merging datasets</span></span>
<span class="line"><span>merged_data &lt;- merge(data1, data2, by = &quot;common_column&quot;) # Merge two datasets by a common column</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br></div></div><h3 id="expanded-examples-for-analyzing-message-campaigns-and-behavioral-changes-in-r" tabindex="-1">Expanded Examples for Analyzing Message Campaigns and Behavioral Changes in R <a class="header-anchor" href="#expanded-examples-for-analyzing-message-campaigns-and-behavioral-changes-in-r" aria-label="Permalink to &quot;Expanded Examples for Analyzing Message Campaigns and Behavioral Changes in R&quot;">​</a></h3><p>When evaluating the effectiveness of message campaigns and measuring changes in behavior, it’s crucial to have a clear analysis strategy. This section expands on basic commands and introduces specific examples relevant to analyzing event data and behavioral changes resulting from messaging campaigns.</p><p>Assuming ‘data’ is a data frame containing your campaign data</p><h4 id="preparing-data-filtering-for-relevant-periods-or-events" tabindex="-1">Preparing Data - Filtering for relevant periods or events <a class="header-anchor" href="#preparing-data-filtering-for-relevant-periods-or-events" aria-label="Permalink to &quot;Preparing Data - Filtering for relevant periods or events&quot;">​</a></h4><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>post_campaign_data &lt;- data[&gt; as.Date(&quot;2023-01-01&quot;) &amp; data$campaign == &quot;Yes&quot;, ](data$date)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h4 id="calculating-mean-engagement-pre-and-post-campaign" tabindex="-1">Calculating Mean Engagement Pre and Post-Campaign <a class="header-anchor" href="#calculating-mean-engagement-pre-and-post-campaign" aria-label="Permalink to &quot;Calculating Mean Engagement Pre and Post-Campaign&quot;">​</a></h4><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>pre_campaign_mean &lt;- mean(data[&lt; as.Date(&quot;2023-01-01&quot;),](data$date)$engagement, na.rm = TRUE)</span></span>
<span class="line"><span>post_campaign_mean &lt;- mean(post_campaign_data$engagement, na.rm = TRUE)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h4 id="comparing-the-means-useful-for-understanding-changes-in-engagement" tabindex="-1">Comparing the Means - Useful for understanding changes in engagement <a class="header-anchor" href="#comparing-the-means-useful-for-understanding-changes-in-engagement" aria-label="Permalink to &quot;Comparing the Means - Useful for understanding changes in engagement&quot;">​</a></h4><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>print(paste(&quot;Pre-campaign mean engagement:&quot;, pre_campaign_mean))</span></span>
<span class="line"><span>print(paste(&quot;Post-campaign mean engagement:&quot;, post_campaign_mean))</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h4 id="t-test-to-statistically-test-the-difference-in-means-pre-and-post-campaign" tabindex="-1">T-Test - To statistically test the difference in means pre and post-campaign <a class="header-anchor" href="#t-test-to-statistically-test-the-difference-in-means-pre-and-post-campaign" aria-label="Permalink to &quot;T-Test - To statistically test the difference in means pre and post-campaign&quot;">​</a></h4><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>t_test_result &lt;- t.test(data[&lt; as.Date(&quot;2023-01-01&quot;),](data$date)$engagement, post_campaign_data$engagement, alternative = &quot;two.sided&quot;, na.action = na.exclude)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h4 id="printing-the-t-test-results" tabindex="-1">Printing the t-test results <a class="header-anchor" href="#printing-the-t-test-results" aria-label="Permalink to &quot;Printing the t-test results&quot;">​</a></h4><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>print(t_test_result)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h4 id="visualizing-engagement-over-time" tabindex="-1">Visualizing Engagement Over Time <a class="header-anchor" href="#visualizing-engagement-over-time" aria-label="Permalink to &quot;Visualizing Engagement Over Time&quot;">​</a></h4><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>ggplot(data, aes(x = date, y = engagement, color = campaign)) +</span></span>
<span class="line"><span>  geom_line() +</span></span>
<span class="line"><span>  geom_point() +</span></span>
<span class="line"><span>  labs(title = &quot;Engagement Over Time&quot;, x = &quot;Date&quot;, y = &quot;Engagement&quot;) +</span></span>
<span class="line"><span>  scale_color_manual(values = c(&quot;No&quot; = &quot;blue&quot;, &quot;Yes&quot; = &quot;red&quot;), name = &quot;Campaign&quot;)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h4 id="visualizing-distribution-of-engagement-pre-vs-post-campaign" tabindex="-1">Visualizing Distribution of Engagement - Pre vs. Post Campaign <a class="header-anchor" href="#visualizing-distribution-of-engagement-pre-vs-post-campaign" aria-label="Permalink to &quot;Visualizing Distribution of Engagement - Pre vs. Post Campaign&quot;">​</a></h4><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>ggplot(data, aes(x = factor(ifelse(date &lt; as.Date(&quot;2023-01-01&quot;), &quot;Pre&quot;, &quot;Post&quot;)), y = engagement, fill = campaign)) +</span></span>
<span class="line"><span>  geom_boxplot() +</span></span>
<span class="line"><span>  labs(title = &quot;Engagement Distribution Pre vs. Post Campaign&quot;, x = &quot;Campaign Period&quot;, y = &quot;Engagement&quot;) +</span></span>
<span class="line"><span>  scale_fill_manual(values = c(&quot;No&quot; = &quot;blue&quot;, &quot;Yes&quot; = &quot;red&quot;), name = &quot;Campaign Active&quot;)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h4 id="correlation-between-engagement-and-another-variable-e-g-sentiment" tabindex="-1">Correlation between Engagement and Another Variable (e.g., sentiment) <a class="header-anchor" href="#correlation-between-engagement-and-another-variable-e-g-sentiment" aria-label="Permalink to &quot;Correlation between Engagement and Another Variable (e.g., sentiment)&quot;">​</a></h4><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>correlation_result &lt;- cor(data$engagement, data$sentiment, use = &quot;complete.obs&quot;)</span></span>
<span class="line"><span>print(paste(&quot;Correlation between engagement and sentiment:&quot;, correlation_result))</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h3 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h3><p>[Analysis] [Sciences]</p>`,116)])])}const h=e(i,[["render",r]]);export{m as __pageData,h as default};
